command-line:
bash -lc 'set -euo pipefail
case "$QSMXT_PREMADE" in default|gre|epi|bet|fast|body|nextqsm) ;; *) echo "Invalid QSMxT premade pipeline: $QSMXT_PREMADE" >&2; exit 2;; esac
mkdir -p /work/home /work/matplotlib /work/bids /output
echo "Converting DICOMs to BIDS..."
qsmxt dicom-convert /input /work/bids || echo "WARNING: one or more series failed to convert; continuing with the series that succeeded" >&2
if ! find /work/bids -name '\''*part-phase*.nii*'\'' | grep -q .; then echo "No QSM-compatible series (multi-echo GRE with phase) found after DICOM conversion" >&2; exit 3; fi
args=(/work/bids --clean-intermediates)
case "$QSMXT_PREMADE" in
default|gre) args+=(--qsm-algorithm rts --unwrapping-algorithm romeo --bf-algorithm pdf --mask-preset robust-threshold --masking-input phase-quality --no-inhomogeneity-correction);;
epi) args+=(--qsm-algorithm rts --unwrapping-algorithm romeo --bf-algorithm pdf --mask-preset robust-threshold --masking-input phase-quality --inhomogeneity-correction);;
bet) args+=(--qsm-algorithm rts --unwrapping-algorithm romeo --bf-algorithm pdf --mask-preset bet --masking-input magnitude --no-inhomogeneity-correction);;
fast) args+=(--qsm-algorithm rts --unwrapping-algorithm romeo --bf-algorithm vsharp --mask-preset bet --masking-input magnitude --no-inhomogeneity-correction);;
body) args+=(--qsm-algorithm tgv --unwrapping-algorithm romeo --bf-algorithm pdf --mask-preset robust-threshold --masking-input phase-quality --no-inhomogeneity-correction);;
nextqsm) args+=(--qsm-algorithm nextqsm --unwrapping-algorithm romeo --bf-algorithm pdf --mask-preset bet --masking-input magnitude --no-inhomogeneity-correction);;
esac
echo "Running QSMxT..."
qsmxt run "${args[@]}"
if ! find /work/bids/derivatives/qsmxt -name '\''*_Chimap.nii*'\'' 2>/dev/null | grep -q .; then echo "QSMxT produced no Chimap output (no QSM-compatible series?)" >&2; exit 3; fi
echo "Backfilling SeriesNumber into Chimap sidecars..."
python3 - /work/bids <<'\''PYBACKFILL'\''
import json, re, sys
from pathlib import Path
bids = Path(sys.argv[1]); deriv = bids / "derivatives" / "qsmxt"
def ents(name):
    return dict(re.findall(r"(?:^|_)(sub|ses|acq|run)-([A-Za-z0-9]+)", name))
src = {}
for pat in ("sub-*/ses-*/anat/*part-phase*.json", "sub-*/anat/*part-phase*.json"):
    for j in bids.glob(pat):
        src.setdefault(tuple(sorted(ents(j.name).items())), j)
patched = 0
for cj in deriv.glob("sub-*/**/anat/*_Chimap.json"):
    s = src.get(tuple(sorted(ents(cj.name).items())))
    if s is None:
        print("WARNING: no source phase sidecar for %s" % cj.name, file=sys.stderr); continue
    sd = json.loads(s.read_text()); cd = json.loads(cj.read_text())
    for k in ("SeriesNumber", "SeriesDescription"):
        if k in sd and k not in cd: cd[k] = sd[k]
    cj.write_text(json.dumps(cd, indent=2)); patched += 1
print("Backfilled SeriesNumber into %d Chimap sidecar(s)" % patched)
PYBACKFILL
cp -a /work/bids/derivatives/. /output/'
